import { subscribeDocumentInvalidation } from "@/lib/syncInvalidation";
import type { CallSignalEvent } from "@/lib/types";
import { gatherComplete, useCalls } from "./calls";
import { useSettings } from "./settings";

const PROTOCOL = "group-voice-1";
const CAPACITY = 4;
const TIMEOUT = 20_000;
const ANNOUNCEMENT_LIMIT = 64;
type Kind = "announce" | "join" | "roster" | "offer" | "answer" | "leave" | "end";
type Packet = {
  group: string;
  meeting: string;
} & (
  | { kind: "announce" | "join" | "leave" | "end" }
  | { kind: "roster"; devices: string[] }
  | { kind: "offer" | "answer"; sdp: string }
);

export function parseGroupVoice(raw: string): Packet | null {
  if (raw.length > 32_768) return null;
  try {
    const value: unknown = JSON.parse(raw);
    if (!value || typeof value !== "object") return null;
    const { protocol, group, meeting, kind, devices, sdp } = value as Record<string, unknown>;
    const validId = (id: unknown): id is string =>
      typeof id === "string" && id.length > 0 && id.length <= 128;
    if (protocol !== PROTOCOL || !validId(group) || !validId(meeting)) return null;
    switch (kind) {
      case "announce": case "join": case "leave": case "end":
        return { group, meeting, kind };
      case "roster":
        return Array.isArray(devices) && devices.length <= CAPACITY &&
          devices.every(validId) && new Set(devices).size === devices.length
          ? { group, meeting, kind, devices }
          : null;
      case "offer": case "answer":
        return typeof sdp === "string" && sdp.length > 0 ? { group, meeting, kind, sdp } : null;
      default: return null;
    }
  } catch {
    return null;
  }
}

type Invite = { group: string; meeting: string; host: string; expires: number };
type Leg = { pc: RTCPeerConnection; abort: AbortController; timer: ReturnType<typeof setTimeout> };
type Session = {
  invite: Invite;
  self: string;
  microphone: MediaStream | null;
  roster: Map<string, string>;
  pending: Set<string>;
  legs: Map<string, Leg>;
  timer?: ReturnType<typeof setTimeout>;
  unsubscribe?: () => void;
};
type State = {
  active: { group: string; host: boolean; joining: boolean } | null;
  invites: Record<string, Invite>;
  audio: Record<string, MediaStream>;
  muted: boolean;
  error: string | null;
};
export const useGroupVoice = create<State>(() => ({
  active: null, invites: {}, audio: {}, muted: false, error: null,
}));
let session: Session | null = null;

function member(groupId: string, deviceId: string) {
  return invoke<string | null>("group_voice_member", { groupId, deviceId }).catch(() => null);
}

function send(to: string, { group, meeting }: Invite, kind: Kind, extra = {}) {
  return calls.signal(to, JSON.stringify({ protocol: PROTOCOL, group, meeting, kind, ...extra }));
}

function closeLeg(room: Session, device: string) {
  const leg = room.legs.get(device);
  if (!leg) return;
  room.legs.delete(device);
  clearTimeout(leg.timer);
  leg.abort.abort();
  leg.pc.ontrack = null;
  leg.pc.onconnectionstatechange = null;
  leg.pc.close();
  useGroupVoice.setState(({ audio }) => ({
    audio: Object.fromEntries(Object.entries(audio).filter(([id]) => id !== device)),
  }));
}

export function stopGroupVoice(notify: boolean = false, end: boolean = false) {
  const room = session;
  session = null;
  if (room) {
    if (notify)
      for (const device of room.roster.keys())
        if (device !== room.self)
          void send(device, room.invite, end && room.self === room.invite.host ? "end" : "leave").catch(() => {});
    room.unsubscribe?.();
    clearTimeout(room.timer);
    for (const device of room.legs.keys()) closeLeg(room, device);
    room.microphone?.getTracks().forEach((track) => track.stop());
  }
  useGroupVoice.setState({ active: null, audio: {}, muted: false, invites: {}, error: null });
}

function fail(room: Session, message: string) {
  if (session !== room) return;
  stopGroupVoice(true);
  useGroupVoice.setState({ error: message });
