export function muteGroupVoice() {
  const muted = !useGroupVoice.getState().muted;
  session?.microphone?.getAudioTracks().forEach((track) => {
    track.enabled = !muted;
  });
  useGroupVoice.setState({ muted });
}

async function openRoom(invite: Invite, self: string, owner: string) {
  if (!self || !owner || session || !useSettings.getState().callsEnabled ||
      useCalls.getState().phase !== "idle") return null;
  const room: Session = {
    invite, self, microphone: null, roster: new Map(), pending: new Set(), legs: new Map(),
  };
  session = room;
  useGroupVoice.setState({ active: { group: invite.group, host: invite.host === self, joining: true }, error: null, muted: false });
  try {
    const account = await member(invite.group, self);
    if (session !== room) return null;
    if (!account || (invite.host !== self && !(await member(invite.group, invite.host))))
      throw new Error("Admission denied");
    if (session !== room) return null;
    room.roster.set(self, account);
    const microphone = await navigator.mediaDevices.getUserMedia({ audio: true });
    if (session !== room) {
      microphone.getTracks().forEach((track) => track.stop());
      return null;
    }
    room.microphone = microphone;
    microphone.getAudioTracks().forEach((track) => { track.enabled = !useGroupVoice.getState().muted; });
