      for (const [device, accountId] of room.roster)
        void member(invite.group, device).then((actual) => {
          if (session !== room || room.roster.get(device) !== accountId || actual === accountId) return;
          if (device === self) {
            fail(room, "Your group voice access changed.");
          } else {
            room.roster.delete(device);
            closeLeg(room, device);
          }
        });
    });
    return room;
  } catch {
    fail(room, "Unable to join group voice. Check group access and microphone permissions.");
    return null;
  }
