export async function joinGroupVoice(invite: Invite, self: string, owner: string) {
  if (Date.now() >= invite.expires) {
    useGroupVoice.setState({ error: "This group voice invitation has expired." });
    return;
  }
  const room = await openRoom(invite, self, owner);
  if (!room || session !== room) return;
  room.timer = setTimeout(() => fail(room, "The group voice meeting did not accept your join."), TIMEOUT);
  try {
    await send(invite.host, invite, "join");
  } catch {
    fail(room, "Could not reach the group voice meeting.");
  }
