import { useEffect, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  joinGroupVoice,
  muteGroupVoice,
  startGroupVoice,
  stopGroupVoice,
  useGroupVoice,
} from "@/store/groupVoice";
import { useSettings } from "@/store/settings";

export function GroupVoiceEntry({
  group, self, owner, members,
}: { group: string; self: string; owner: string; members: string[] }) {
  const enabled = useSettings((state) => state.callsEnabled);
  const invite = useGroupVoice((state) => state.invites[group]);
  const active = useGroupVoice((state) => state.active);
  if (!enabled || active) return null;
  return (
    <Button
      type="button"
      variant="ghost"
      onClick={() => {
        if (invite && invite.expires > Date.now()) void joinGroupVoice(invite, self, owner);
        else void startGroupVoice(group, self, owner, members);
      }}
    >
      {invite && invite.expires > Date.now() ? "Join group voice" : "Start group voice"}
    </Button>
  );
}

function RemoteAudio({ stream }: { stream: MediaStream }) {
  const element = useRef<HTMLAudioElement>(null);
  const [blocked, setBlocked] = useState(false);
  useEffect(() => {
    const player = element.current;
    if (!player) return;
    let live = true;
    player.srcObject = stream;
    void player.play().then(() => { if (live) setBlocked(false); }, () => {
      if (live) setBlocked(true);
    });
    return () => {
      live = false;
      player.pause();
      player.srcObject = null;
    };
  }, [stream]);
  return (
    <>
      <audio ref={element} autoPlay />
      {blocked && <Button onClick={() => {
        void element.current?.play().then(() => setBlocked(false), () => setBlocked(true));
      }}>Play participant audio</Button>}
    </>
  );
}

export function GroupVoiceControls() {
  const { active, audio, muted, error } = useGroupVoice();
  if (!active && !error) return null;
  return (
    <section aria-label="Group voice" className="absolute bottom-6 right-6 z-40 rounded-lg border bg-popover p-4 text-popover-foreground shadow-elevation">
      {active && (
        <div className="flex items-center gap-2">
          <span role="status">{active.joining ? "Joining group voice…" : "Group voice"}</span>
          <Button onClick={muteGroupVoice} aria-pressed={muted}>{muted ? "Unmute" : "Mute"}</Button>
          <Button onClick={() => stopGroupVoice(true)}>Leave</Button>
          {active.host && <Button variant="destructive" onClick={() => stopGroupVoice(true, true)}>End meeting</Button>}
        </div>
      )}
      {error && (
        <div className="flex items-center gap-2">
          <span role="alert">{error}</span>
          <Button onClick={() => useGroupVoice.setState({ error: null })}>Dismiss</Button>
        </div>
      )}
      {Object.entries(audio).map(([device, stream]) => <RemoteAudio key={device} stream={stream} />)}
    </section>
  );
}
